#[path="../native-prepared-solvers/prepared.rs"]mod prepared;
#[path="../native-prepared-solvers/table_oracle.rs"]mod table_oracle;
#[path="../batched/inverse.rs"]mod inverse;
use hec_native_ic::{counted,instance::pick_instance,jac::Curve,poly::Poly,fp::Fp,rng::Rng};
use std::collections::BTreeMap;
fn key<'a>(s:&'a str,k:&str)->Option<&'a str>{s.split_whitespace().find_map(|s|s.strip_prefix(&format!("{k}=")))}
fn brute(mut h:Poly,c:&Curve)->Option<BTreeMap<u64,u32>>{let mut r=BTreeMap::new();for x in 0..c.fp.p{while h.deg()>0&&h.eval(x,&c.fp)==0{h=h.div_exact(&Poly::x_minus(x,&c.fp),&c.fp);*r.entry(x).or_insert(0)+=1;}}if h.deg()==0{Some(r)}else{None}}
#[derive(Debug)]struct Trial{status:&'static str,inputs:Vec<(usize,i64)>,h:Vec<u64>,roots:Vec<(u64,u32)>,a:Option<u64>,b:Option<u64>,k:Option<u64>}
fn attempt(c:&Curve,ell:u64,prep:&prepared::Prepared,tags:&BTreeMap<usize,(u64,u64)>,rng:&mut Rng)->Trial{let ids:Vec<_>=tags.keys().copied().collect();assert!(ids.len()>=c.g+1);let mut selected=vec![];while selected.len()<c.g+1{let j=ids[rng.below(ids.len()as u64)as usize];if !selected.contains(&j){selected.push(j);}}let mut inputs=vec![];let mut points=vec![];let mut u=Poly::one();for j in selected{let sign=if rng.below(2)==0{1}else{-1};let(x,y)=prep.fb[j];let y=if sign==1{y}else{c.fp.neg(y)};inputs.push((j,sign));points.push((x,y));u=u.mul(&Poly::x_minus(x,&c.fp),&c.fp);}
let mut bases=vec![];let mut den=vec![];for &(x,_)in &points{let mut coeff=vec![0;c.g+1];coeff[c.g]=1;for i in(0..c.g).rev(){coeff[i]=c.fp.add(u.c[i+1],c.fp.mul(x,coeff[i+1]));}let q=Poly::from_coeffs(&coeff);assert_eq!(q.mul(&Poly::x_minus(x,&c.fp),&c.fp),u);den.push(q.eval(x,&c.fp));bases.push(q);}let inv=inverse::invert(&den,&c.fp);let mut v=Poly::zero();for(i,&(_,y))in points.iter().enumerate(){v=v.add(&bases[i].scale(c.fp.mul(y,inv[i]),&c.fp),&c.fp);}for &(x,y)in &points{assert_eq!(v.eval(x,&c.fp),y);}let norm=c.f.sub(&v.mul(&v,&c.fp),&c.fp);let(h,rem)=norm.divrem(&u,&c.fp);assert!(rem.is_zero());assert_eq!(h.deg(),c.g as isize);assert_eq!(h.lc(),1);assert_eq!(u.mul(&h,&c.fp),norm);
let split=table_oracle::split(&h,&c.fp,&mut table_oracle::OracleStats::default(),&prep.roots);let truth=brute(h,c);assert_eq!(split.is_some(),truth.is_some());let mut out=Trial{status:"nonsplit",inputs,h:h.c[..h.n].to_vec(),roots:vec![],a:None,b:None,k:None};let Some(split)=split else{return out;};let roots:BTreeMap<_,_>=split.as_slice().iter().copied().collect();assert_eq!(roots,truth.unwrap());out.roots=split.as_slice().to_vec();let mut native=c.zero();for &(x,y)in &points{native=c.add_place(&native,x,y);}let mut signed=out.inputs.clone();let index:BTreeMap<_,_>=prep.fb.iter().enumerate().map(|(j,&(x,_))|(x,j)).collect();let mut all_grounded=true;for &(x,mult)in split.as_slice(){let y=v.eval(x,&c.fp);let j=index[&x];let sign=if y==prep.fb[j].1{1}else{assert_eq!(y,c.fp.neg(prep.fb[j].1));-1};signed.push((j,sign*mult as i64));all_grounded&=tags.contains_key(&j);for _ in 0..mult{native=c.add_place(&native,x,y);}}assert!(c.is_zero(&native),"principal relation");if !all_grounded{out.status="ungrounded";return out;}let f=Fp::new(ell);let(mut a,mut b)=(0,0);for(j,mult)in signed{let(x,y)=tags[&j];let s=f.from_i64(mult);a=f.add(a,f.mul(s,x));b=f.add(b,f.mul(s,y));}out.a=Some(a);out.b=Some(b);if b==0{assert_eq!(a,0,"dependent relation consistency");out.status="zero_signature";}else{out.k=Some(f.mul(f.neg(a),f.inv(b)));out.status="determining";}out}
fn main(){counted::disable();let raw=include_str!("../native-quotient-descriptor/CONTROL.txt");let mut trials=0;let mut covered=0;let mut branch_covered=0;for line in include_str!("../native-pencil-3lp/INSTANCES.tsv").lines().skip(1){let vs:Vec<_>=line.split('\t').collect();let g:usize=vs[0].parse().unwrap();let p:u64=vs[1].parse().unwrap();let ell:u64=vs[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c.to_string(),vs[2]);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),vs[4]);let c=&inst.curve;let prep=prepared::prepare(c,true);let mut target_rng=Rng::new(2026111800^p^((g as u64)<<32));for case in 0..2{let sm=if case==0{1}else{17};let d=c.mul(&inst.d1,sm);let expected=1+target_rng.below(ell-1);let target=c.mul(&d,expected);let matches=|l:&str|key(l,"g")==Some(vs[0])&&key(l,"p")==Some(vs[1])&&key(l,"sm")==Some(sm.to_string().as_str())&&key(l,"case")==Some(case.to_string().as_str())&&key(l,"rep")==Some("0");let tags:BTreeMap<usize,(u64,u64)>=raw.lines().filter(|l|l.starts_with("POINT ")&&matches(l)).map(|l|(key(l,"j").unwrap().parse().unwrap(),(key(l,"alpha").unwrap().parse().unwrap(),key(l,"beta").unwrap().parse().unwrap()))).collect();assert!(tags.len()>=g+1);let mut rng=Rng::new(2026112200^p^((g as u64)<<32)^case as u64);let mut first=None;let mut counts=BTreeMap::<&str,usize>::new();let mut branch_found=false;for(&j,&(a,b))in &tags{if prep.fb[j].1==0&&b!=0{let f=Fp::new(ell);let k=f.mul(f.neg(a),f.inv(b));assert_eq!(k,expected);assert_eq!(c.mul(&d,k),target);println!("BRANCH_CONTROL g={g} p={p} sm={sm} case={case} j={j} candidate={k}");branch_found=true;}}if branch_found{branch_covered+=1;}
for trial in 0..128{let out=attempt(c,ell,&prep,&tags,&mut rng);*counts.entry(out.status).or_default()+=1;if let(Some(a),Some(b))=(out.a,out.b){let f=Fp::new(ell);assert_eq!(f.add(a,f.mul(b,expected)),0);}if let Some(k)=out.k{assert_eq!(k,expected);assert_eq!(c.mul(&d,k),target);first.get_or_insert(trial+1);}println!("TRIAL g={g} p={p} sm={sm} case={case} trial={} result={out:?}",trial+1);trials+=1;}if first.is_some(){covered+=1;}println!("SUMMARY g={g} p={p} sm={sm} case={case} grounded={} first={first:?} branch_control={branch_found} counts={counts:?}",tags.len());}}assert_eq!(trials,2816);eprintln!("PASS trials={trials} fixtures=22 determining_fixtures={covered} branch_control_fixtures={branch_covered} all_128_including_after_success=true brute_splitting=true native_principal_and_candidates=true structural_only_not_cold_or_tenfold=true");}
